def lru_cache_manual(capacity):
    class LRUCache:
        def __init__(self, capacity):
            self.capacity = capacity
            self.cache = {}
            self.order = []

        def get(self, k):
            if k in self.cache:
                # Mover el elemento al final (actualizar orden)
                self.order.remove(k)
                self.order.append(k)
                return self.cache[k]
            return -1

        def put(self, k, v):
            if k in self.cache:
                # Actualizar valor y mover al final
                self.order.remove(k)
            elif len(self.order) >= self.capacity:
                # Eliminar el más antiguo (primer elemento)
                oldest = self.order.pop(0)
                del self.cache[oldest]

            # Agregar o actualizar
            self.cache[k] = v
            self.order.append(k)

    return LRUCache(capacity)
