def merge_intervalos(intervalos):
    if not intervalos:
        return []

    intervalos.sort(key=lambda x: x[0])
    fusionados = [intervalos[0]]

    for actual in intervalos[1:]:
        ultimo = fusionados[-1]
        if actual[0] <= ultimo[1]:
            ultimo[1] = max(ultimo[1], actual[1])
        else:
            fusionados.append(actual)

