def bfs_camino(grafo, origen, destino):
    if origen not in grafo or destino not in grafo:
        return None

    cola = deque([[origen]])
    visitados = {origen}

    while cola:
        camino = cola.popleft()
        nodo = camino[-1]

        if nodo == destino:
            return camino

        for vecino in grafo.get(nodo, []):
            if vecino not in visitados:
                visitados.add(vecino)
                cola.append(camino + [vecino])

    return None
