from collections import OrderedDict

def lru_cache_manual(capacity: int):
    cache = OrderedDict()

    class LRUCache:
        def get(self, k):
            if k not in cache:
                return -1
            cache.move_to_end(k)
            return cache[k]

        def put(self, k, v):
            if k in cache:
                cache.move_to_end(k)
            cache[k] = v
            if len(cache) > capacity:
                cache.popitem(last=False)

    return LRUCache()
