def mas_largo_sin_repetir(s: str) -> int:
    vistos = {}
    inicio = 0
    max_longitud = 0

    for fin, caracter in enumerate(s):
        if caracter in vistos and vistos[caracter] >= inicio:
            inicio = vistos[caracter] + 1
        vistos[caracter] = fin
        max_longitud = max(max_longitud, fin - inicio + 1)

    return max_longitud
